%[text] Scientific Programming - TCGA Ovarian Cancer dataset
%[text] 02 - Clinical exploratory data analysis
clear;
clc;
close all;

load("results/cleaned_data.mat");

if ~exist("figures", "dir")
    mkdir("figures");
end
%%
%[text] 1\. Cohort Overview
nPatients = height(clinical_dfs);
nEvents = sum(dfsEvent);
nCensored = sum(~dfsEvent);

fprintf("DFS cohort: %d patients\n", nPatients); %[output:861d1162]
fprintf("Recurrence/progression events: %d\n", nEvents); %[output:528faa71]
fprintf("Censored observations: %d\n", nCensored); %[output:628ece62]
%%
%[text] 2\. Clinical variables distribution
stageTable = groupcounts(clinical_dfs, "TUMOR_STAGE_2009");
gradeTable = groupcounts(clinical_dfs, "GRADE");
residualTable = groupcounts(clinical_dfs, "TUMOR_RESIDUAL_DISEASE");

disp("Tumor stage distribution:") %[output:7599002d]
disp(stageTable) %[output:6ede43bc]

disp("Grade distribution:") %[output:5103dcd7]
disp(gradeTable) %[output:4457070f]

disp("Residual disease distribution:") %[output:5ada6516]
disp(residualTable) %[output:8fffefce]
