%[text] Candidate clinical variables for DFS analysis
%[text] - TUMOR\_STAGE\_2009
%[text] - GRADE
%[text] - TUMOR\_RESIDUAL\_DISEASE
%[text] - TMB\_NONSYNONYMOUS \
%[text] Treatment-response variables (PLATINUM\_STATUS and PRIMARY\_THERAPY\_OUTCOME\_SUCCESS) contain information after treatment.
%[text] DFS\_STATUS and DFS\_MONTHS define the outcome.
%%
%[text] 3\. DFS event proportions by categorical clinical variables
%[text] event = patient had a documented recurrence/progression of the cancer during follow up.
%[text] It does not distinguish early recurrence from late recurrence. 
clinicalVariables = { ...
    "TUMOR_STAGE_2009", ...
    "GRADE", ...
    "TUMOR_RESIDUAL_DISEASE"};

for v = 1:numel(clinicalVariables) %[output:group:4d984bfb]

    variableName = clinicalVariables{v};
    values = string(clinical_dfs.(variableName));

    % Remove missing values
    valid = values ~= "NA" & ~ismissing(values);

    values = categorical(values(valid));
    event = dfsEvent(valid);

    fprintf("\n%s\n", variableName); %[output:8f4bc78d] %[output:3659d553] %[output:12adbb09]

    groups = categories(values);

    for i = 1:numel(groups)

        idx = values == groups{i};

        fprintf("%s: %d/%d events (%.1f%%)\n", ... %[output:56236ebf] %[output:8638dfe4] %[output:56a140f7]
            groups{i}, ... %[output:56236ebf] %[output:8638dfe4] %[output:56a140f7]
            sum(event(idx)), ... %[output:56236ebf] %[output:8638dfe4] %[output:56a140f7]
            sum(idx), ... %[output:56236ebf] %[output:8638dfe4] %[output:56a140f7]
            100*mean(event(idx))); %[output:56236ebf] %[output:8638dfe4] %[output:56a140f7]
    end

    [~, chi2, p] = crosstab(values, event);

    fprintf("Chi-square = %.3f, p = %.4g\n", chi2, p); %[output:8c1ed8e2] %[output:56efc328] %[output:37a98fdd]
end %[output:group:4d984bfb]
%[text] Event-rate plot for each variable:
%%\ TUMOR STAGE

validStage = clinical_dfs.TUMOR_STAGE_2009 ~= "NA";

stage = categorical( ...
    clinical_dfs.TUMOR_STAGE_2009(validStage));

stage = reordercats(stage, { ...
    'IIA','IIB','IIC','IIIA','IIIB','IIIC','IV'});

event = dfsEvent(validStage);

stageGroups = categories(stage);

eventRate = zeros(numel(stageGroups),1);
nGroup = zeros(numel(stageGroups),1);

for i = 1:numel(stageGroups)

    idx = stage == stageGroups{i};

    nGroup(i) = sum(idx);
    eventRate(i) = 100 * mean(event(idx));

end

figure; %[output:03179e74]

bar(categorical(stageGroups, stageGroups, ... %[output:03179e74]
    'Ordinal', true), eventRate); %[output:03179e74]

