%[text] The test showed a significant difference in DFS across residual-disease groups. Patients with no macroscopic residual disease showed the best disease-free survival over time. 
%%
function [chi2, p, df] = logrankTest(time, event, group)

    time = time(:);
    event = logical(event(:));
    group = categorical(group(:));

    groupNames = categories(group);
    k = numel(groupNames);

    O = zeros(k,1);   % observed events
    E = zeros(k,1);   % expected events
    V = zeros(k,k);   % variance-covariance matrix

    eventTimes = unique(time(event));

    for t = eventTimes'

        atRisk = time >= t;
        eventsNow = event & time == t;

        Y = sum(atRisk);
        d = sum(eventsNow);

        Yg = zeros(k,1);
        dg = zeros(k,1);

        for g = 1:k
            inGroup = group == groupNames{g};

            Yg(g) = sum(atRisk & inGroup);
            dg(g) = sum(eventsNow & inGroup);
        end

        O = O + dg;
        E = E + d * (Yg / Y);

        if Y > 1
            pRisk = Yg / Y;

            V = V + ...
                d * (Y - d) / (Y - 1) * ...
                (diag(pRisk) - pRisk * pRisk');
        end
    end

    difference = O - E;

    chi2 = difference' * pinv(V) * difference;
    df = k - 1;
    p = 1 - chi2cdf(chi2, df);

end

